function fewestBuses(routes: number[][], source: number, target: number): number {
  if (source === target) return 0;
  const adj = new Map<number, Set<number>>();
  for (const route of routes) {
    for (const a of route) {
      if (!adj.has(a)) adj.set(a, new Set());
      for (const b of route) if (a !== b) adj.get(a)!.add(b);
    }
  }
  if (!adj.has(source)) return -1;
  const dist = new Map<number, number>([[source, 0]]);
  const queue = [source];
  for (let h = 0; h < queue.length; h++) {
    const s = queue[h];
    for (const nb of adj.get(s)!) {
      if (dist.has(nb)) continue;
      dist.set(nb, dist.get(s)! + 1);
      if (nb === target) return dist.get(nb)!;
      queue.push(nb);
    }
  }
  return -1;
}

