function fewestBuses(routes: number[][], source: number, target: number): number {
  if (source === target) return 0;
  const stopToBuses = new Map<number, number[]>();
  routes.forEach((route, i) => {
    for (const s of route) {
      if (!stopToBuses.has(s)) stopToBuses.set(s, []);
      stopToBuses.get(s)!.push(i);
    }
  });
  const usedBus = new Array(routes.length).fill(false);
  const doneStop = new Set<number>([source]);
  let layer: number[] = [];
  for (const b of stopToBuses.get(source) ?? []) { usedBus[b] = true; layer.push(b); }
  for (let buses = 1; layer.length; buses++) {
    const next: number[] = [];
    for (const b of layer) {
      for (const s of routes[b]) {
        if (s === target) return buses;
        if (doneStop.has(s)) continue;
        doneStop.add(s);
        for (const nb of stopToBuses.get(s)!) {
          if (!usedBus[nb]) { usedBus[nb] = true; next.push(nb); }
        }
      }
    }
    layer = next;
  }
  return -1;
}

